The route is registered unauthenticated (no preHandler) and bypasses admin auth by design:
  // Path mounts under same prefix as admin (/api/v1/admin) but bypasses auth.  // line 482

  server.post('/horoscope/prewarm', async (request, reply) => {
    const cronSecret = process.env.CRON_SECRET;
    if (cronSecret) {                                              // line 202 — guard means: if NO env, skip ALL auth
      const token = (request.headers['x-cron-secret'] as string | undefined) ?? '';
      if (token !== cronSecret) {                                  // line 204 — plain !==, NOT constant-time
        return reply.code(401).send({ error: 'Invalid cron secret.' });
      }
    }
    const result = await prewarmDailyHoroscopes();                 // line 208 — runs if env unset OR token matches
    return { prewarmed: result };
  });

